### Structure Definition and Array of Structures in C

A structure in C is a user-defined data type that groups related variables of different types. To represent multiple cars, we define `struct myCar` and declare an array of this structure.

```c
#include <stdio.h>

// Definition of structure myCar
struct myCar {
    char make[50];
    char model[50];
    int year;
};

int main() {
    // Declaring an array of 3 structure variables
    struct myCar cars[3] = {
        {"Toyota", "Corolla", 2020},
        {"Honda", "Civic", 2022},
        {"Ford", "Mustang", 2021}
    };

    printf("Car Details:\n");
    printf("%-15s %-15s %-10s\n", "Make", "Model", "Year");
    printf("-------------------------------------------\n");

    for (int i = 0; i < 3; i++) {
        printf("%-15s %-15s %-10d\n", cars[i].make, cars[i].model, cars[i].year);
    }

    return 0;
}

```

**Explanation:**
1. `struct myCar`: Declares structure template containing member variables `make` (string), `model` (string), and `year` (integer).
2. `struct myCar cars[3]`: Allocates contiguous memory for an array of 3 car records on the stack.
3. `cars[i].member`: Accesses each member of the $i$-th structure element using the member access dot operator (`.`).

### Solution using `struct student`

To identify students across 5 departments who have the highest CGPA within the range $[9.0, 9.5]$, we define `struct student` and filter candidate students.

```c
#include <stdio.h>
#include <string.h>

#define NUM_DEPTS 5
#define MAX_STUDENTS 10

// Mandatory struct student
struct student {
    int id;
    char name[50];
    char department[30];
    float cgpa;
};

int main() {
    // Sample student database from 5 departments
    struct student students[MAX_STUDENTS] = {
        {101, "Aarav", "CSE", 9.4},
        {102, "Diya", "ECE", 9.2},
        {103, "Karan", "MECH", 8.8},
        {104, "Sneha", "IT", 9.5},
        {105, "Vikram", "CIVIL", 9.1},
        {106, "Pooja", "CSE", 9.5},
        {107, "Rahul", "ECE", 9.3},
        {108, "Ananya", "IT", 9.4},
        {109, "Rohan", "MECH", 9.0},
        {110, "Meera", "CIVIL", 9.2}
    };

    // Step 1: Find the maximum CGPA strictly within the range [9.0, 9.5]
    float maxCgpa = -1.0;
    for (int i = 0; i < MAX_STUDENTS; i++) {
        if (students[i].cgpa >= 9.0 && students[i].cgpa <= 9.5) {
            if (students[i].cgpa > maxCgpa) {
                maxCgpa = students[i].cgpa;
            }
        }
    }

    // Step 2: Display all students who achieved this highest CGPA in [9.0, 9.5]
    if (maxCgpa < 0) {
        printf("No students found with CGPA between 9.0 and 9.5.\n");
    } else {
        printf("Highest CGPA in range [9.0 - 9.5] is: %.2f\n\n", maxCgpa);
        printf("%-8s %-15s %-15s %-6s\n", "ID", "Name", "Department", "CGPA");
        printf("----------------------------------------------\n");
        for (int i = 0; i < MAX_STUDENTS; i++) {
            if (students[i].cgpa == maxCgpa) {
                printf("%-8d %-15s %-15s %-6.2f\n", 
                       students[i].id, students[i].name, students[i].department, students[i].cgpa);
            }
        }
    }

    return 0;
}

```

**Output:**

```text
Highest CGPA in range [9.0 - 9.5] is: 9.50

ID       Name            Department      CGPA  
----------------------------------------------
104      Sneha           IT              9.50  
106      Pooja           CSE             9.50
```

### Deleting Node `Temp` in a Singly Linked List

Based on the problem scenario and diagram where a node `Temp` is targeted for deletion from the singly linked list:

#### Case 1: When `Temp` is the Head Node (`Temp == Head`)

```text
Algorithm DeleteHeadNode(Head, Temp):
    1. If Head == NULL then
           Print "List is empty"
           Return NULL
       End If
    2. Set Temp = Head
    3. Set Head = Head.next
    4. Free(Temp)
    5. Return Head

```

#### Case 2: When `Temp` is an Arbitrary Node in the List

```text
Algorithm DeleteNode(Head, Temp):
    1. If Head == NULL or Temp == NULL then
           Return Head
       End If
    2. If Head == Temp then
           Head = Head.next
           Free(Temp)
           Return Head
       End If
    3. Set Prev = Head
    4. While Prev.next != NULL and Prev.next != Temp do
           Prev = Prev.next
       End While
    5. If Prev.next == Temp then
           Prev.next = Temp.next
           Free(Temp)
       Else
           Print "Node Temp not found in list"
       End If
    6. Return Head

```

#### C Implementation Snippet:

```c
struct Node {
    int data;
    struct Node* next;
};

struct Node* deleteNode(struct Node* head, struct Node* temp) {
    if (head == NULL || temp == NULL) return head;
    if (head == temp) {
        head = head->next;
        free(temp);
        return head;
    }
    struct Node* prev = head;
    while (prev->next != NULL && prev->next != temp) {
        prev = prev->next;
    }
    if (prev->next == temp) {
        prev->next = temp->next;
        free(temp);
    }
    return head;
}

```
**Complexity:** Time Complexity is $O(n)$ in the worst case (traversal to find `Temp`), and Space Complexity is $O(1)$.

### Structure Definition and Function for Hotel Management

#### 1. Pseudocode:

```text
Structure Hotel:
    name: String
    address: String
    grade: Character (e.g., 'A', 'B', 'C')
    num_rooms: Integer
    room_charges: Float
End Structure

Procedure PrintHotelsByGrade(hotelList, totalHotels, targetGrade):
    found = False
    Print "Hotels with Grade: ", targetGrade
    For i = 0 to totalHotels - 1 do:
        If hotelList[i].grade == targetGrade then
            Print "- Hotel Name: ", hotelList[i].name, 
                  " | Address: ", hotelList[i].address, 
                  " | Charges: ", hotelList[i].room_charges
            found = True
        End If
    End For
    If found == False then
        Print "No hotels found with grade ", targetGrade
    End If
End Procedure

```

#### 2. C Program Implementation:

```c
#include <stdio.h>
#include <string.h>

struct Hotel {
    char name[100];
    char address[150];
    char grade;           // e.g., 'A', 'B', 'C'
    int num_rooms;
    float room_charges;
};

void printHotelsByGrade(struct Hotel hotels[], int n, char targetGrade) {
    int count = 0;
    printf("\n--- Hotels of Grade '%c' ---\n", targetGrade);
    for (int i = 0; i < n; i++) {
        if (hotels[i].grade == targetGrade) {
            printf("Hotel Name    : %s\n", hotels[i].name);
            printf("Address       : %s\n", hotels[i].address);
            printf("Rooms         : %d\n", hotels[i].num_rooms);
            printf("Room Charges  : $%.2f\n", hotels[i].room_charges);
            printf("----------------------------------------\n");
            count++;
        }
    }
    if (count == 0) {
        printf("No hotels found with grade '%c'.\n", targetGrade);
    }
}

int main() {
    struct Hotel list[4] = {
        {"Grand Palace", "12 Marina Bay, Chennai", 'A', 120, 5500.0},
        {"Ocean View", "45 Beach Road, Chennai", 'B', 60, 3200.0},
        {"Royal Residency", "88 Central Ave, Chennai", 'A', 200, 7000.0},
        {"Budget Stay", "14 Station Rd, Chennai", 'C', 30, 1500.0}
    };

    printHotelsByGrade(list, 4, 'A');
    return 0;
}
```

### Circular Doubly Linked List (CDLL) Implementation

**Initial CDLL:**  
`[Item A] ⇄ [Item B] ⇄ [Item C] ⇄ [Item D] ⇄ [Item E] ⇄ [Item F] ⇄ (loops back to [Item A])`  
Here, `Head` points to `Item A` and `Tail` is `Head->prev` which points to `Item F`.

**Operations Required:**  
1. Remove `Item A` (the current head node).
2. Insert `Item G` in place of `Item A` (becoming the new head node linked between `Item F` and `Item B`).

**Final CDLL:**  
`[Item G] ⇄ [Item B] ⇄ [Item C] ⇄ [Item D] ⇄ [Item E] ⇄ [Item F] ⇄ (loops back to [Item G])`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    char item[20];
    struct Node* prev;
    struct Node* next;
};

// Function to insert at the end of CDLL
struct Node* insertEnd(struct Node* head, const char* name) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    strcpy(newNode->item, name);

    if (head == NULL) {
        newNode->next = newNode;
        newNode->prev = newNode;
        return newNode;
    }

    struct Node* tail = head->prev;
    tail->next = newNode;
    newNode->prev = tail;
    newNode->next = head;
    head->prev = newNode;
    return head;
}

// Function to replace Item A with Item G at head
struct Node* replaceHead(struct Node* head, const char* oldName, const char* newName) {
    if (head == NULL) return NULL;

    // Check if head matches oldName
    if (strcmp(head->item, oldName) == 0) {
        struct Node* tail = head->prev;
        struct Node* second = head->next;
        struct Node* oldNode = head;

        // Create new node for Item G
        struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
        strcpy(newNode->item, newName);

        if (head->next == head) { // Only one element
            newNode->next = newNode;
            newNode->prev = newNode;
            free(oldNode);
            return newNode;
        }

        // Link newNode in place of head
        newNode->next = second;
        newNode->prev = tail;
        tail->next = newNode;
        second->prev = newNode;

        free(oldNode);
        return newNode; // New head is Item G
    }
    return head;
}

// Function to display CDLL
void display(struct Node* head) {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }
    struct Node* temp = head;
    do {
        printf("[%s] <-> ", temp->item);
        temp = temp->next;
    } while (temp != head);
    printf("(wraps to %s)\n", head->item);
}

int main() {
    struct Node* list = NULL;
    list = insertEnd(list, "Item A");
    list = insertEnd(list, "Item B");
    list = insertEnd(list, "Item C");
    list = insertEnd(list, "Item D");
    list = insertEnd(list, "Item E");
    list = insertEnd(list, "Item F");

    printf("Initial Shopping List:\n");
    display(list);

    // Remove Item A and add Item G in its place
    list = replaceHead(list, "Item A", "Item G");

    printf("\nUpdated Shopping List (Item A removed, Item G added):\n");
    display(list);

    return 0;
}

```

**Output:**

```text
Initial Shopping List:
[Item A] <-> [Item B] <-> [Item C] <-> [Item D] <-> [Item E] <-> [Item F] <-> (wraps to Item A)

Updated Shopping List (Item A removed, Item G added):
[Item G] <-> [Item B] <-> [Item C] <-> [Item D] <-> [Item E] <-> [Item F] <-> (wraps to Item G)
```
